<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted} from 'vue'
import EmailDestinations from './EmailDestinations.vue'
import {api,notify} from '../composables/api'
import type {AlertConfiguration,TestDeliveryOperation} from '../types'
const props=defineProps<{testing?:boolean}>(),emit=defineEmits<{saved:[];verified:[];skip:[]}>(),mode=ref('email'),email=ref<InstanceType<typeof EmailDestinations>|null>(null),config=ref<AlertConfiguration|null>(null),selected=ref(''),confirmation=ref(false),saving=ref(false),operation=ref<TestDeliveryOperation|null>(null),error=ref(''),polling=ref(false)
const others=computed(()=>config.value?.connections.filter(c=>['slack','webhook'].includes(c.provider)&&c.enabled&&!c.disconnected)??[])
let timer:ReturnType<typeof setTimeout>|undefined,disposed=false,attempt=0,key=crypto.randomUUID()
onMounted(async()=>{try{config.value=await api('/alerting');selected.value=others.value[0]?.id??''}catch(e){error.value=e instanceof Error?e.message:'Destinations unavailable.'}});onUnmounted(()=>{disposed=true;clearTimeout(timer)})
function confirmLeave(){return email.value?.confirmLeave()??true}defineExpose({confirmLeave})
function choose(value:string){if(confirmLeave())mode.value=value}
async function test(){saving.value=true;try{const result=await api<{id:string}>('/alerting/tests','POST',{client_key:key,connections:[selected.value]});key=crypto.randomUUID();confirmation.value=false;operation.value={id:result.id,items:[],queue_asynchronous:true};attempt=0;await status()}catch(e){error.value=e instanceof Error?e.message:'Test could not be queued.'}finally{saving.value=false}}
async function status(){if(!operation.value||disposed)return;try{operation.value=await api('/alerting/tests/'+operation.value.id);attempt++;if(operation.value?.items.length&&operation.value.items.every(i=>i.status==='sent')){polling.value=false;notify('The selected notification transport accepted the test.');emit('verified')}else if(operation.value?.items.some(i=>['pending','processing','retrying'].includes(i.status))&&attempt<15){polling.value=true;timer=setTimeout(status,2000)}else polling.value=false}catch(e){polling.value=false;error.value=e instanceof Error?e.message:'Test status unavailable.'}}
</script>
<template><section><p class="help">Notifications are optional. Configure a destination and review a rule, or explicitly continue without them. Production rule filters do not change the environment of a local test.</p><div class="inline-actions spacing"><RouterLink to="/integrations" class="button">Configure integrations</RouterLink><RouterLink to="/alerts" class="button">Review alert rules</RouterLink></div><nav class="notification-methods" aria-label="Setup notification method"><button class="button" :class="{selected:mode==='email'}" @click="choose('email')">Email</button><button class="button" :class="{selected:mode==='other'}" @click="choose('other')">Slack / webhook</button></nav><EmailDestinations v-if="mode==='email'" ref="email" :testing="testing" setup @saved="emit('saved')" @verified="emit('verified')"/><section v-else class="setup-other-destination"><h3>{{testing?'Verify the active transport':'Use a configured destination'}}</h3><p v-if="!others.length">No enabled Slack or webhook target is configured yet.</p><label v-else class="field">Notification destination<select v-model="selected"><option v-for="c in others" :key="c.id" :value="c.id">{{c.provider}} · {{c.name}} · {{c.display}}</option></select></label><p v-if="error" class="notice danger" role="alert">{{error}}</p><button v-if="!testing" class="button primary" :disabled="!selected" @click="emit('saved')">Continue to delivery test</button><button v-else class="button primary" :disabled="!selected||saving||polling" @click="confirmation=true">Send synthetic test</button><div v-if="confirmation" class="notice warning spacing"><div><strong>Confirm selected destination</strong><p>Queue one labeled message using the active connection configuration. This uses the selected transport and does not enable automatic rules.</p><div class="inline-actions"><button class="button" :disabled="saving" @click="test">Confirm queued test</button><button class="button" @click="confirmation=false">Cancel test</button></div></div></div><div v-if="operation" class="notice neutral spacing" role="status"><div><p v-if="!operation.queue_asynchronous">No supported asynchronous queue is configured; durable work remains pending.</p><ul><li v-for="d in operation.items" :key="d.id"><RouterLink :to="'/alerts/history/'+d.id">{{d.destination_name}} · {{d.status}}</RouterLink><span v-if="d.reason"> · {{d.reason}}</span></li></ul><button class="button" :disabled="polling" @click="status">Refresh delivery check</button></div></div></section><div class="form-actions"><button class="text-link" :disabled="saving||polling" @click="emit('skip')">Continue without notifications</button></div><p class="help">A GitHub repository read check is not a notification-delivery test.</p></section></template>
